#!/usr/bin/env python3
"""cut(1) work-alike: cut.py [-s] -d DELIM -f LIST [FILE...]

Select fields from each line of input. LIST supports:
  N      field N (1-based)
  N-M    fields N through M inclusive
  N-     fields N through end of line
  -M     fields 1 through M
Comma-separated combinations are allowed, e.g. 1,3 or 2-4 or 3-.

Exit status 2 on usage errors (bad delimiter, invalid/reversed field ranges).
"""

import argparse
import sys


def parse_field_list(spec):
    """Parse a field list spec into a list of (start, end) inclusive ranges.

    Raises ValueError with a descriptive message on invalid specs,
    including field 0 and reversed ranges.
    """
    ranges = []
    for part in spec.split(","):
        part = part.strip()
        if not part:
            raise ValueError(f"invalid field value: empty item in list '{spec}'")
        if "-" in part[1:] or part.startswith("-"):
            # Range form: N-M, N-, -M
            if part.startswith("-"):
                start_str, end_str = "", part[1:]
            else:
                start_str, _, end_str = part.partition("-")
            if start_str == "" and end_str == "":
                raise ValueError("invalid range with no endpoints: '-'")
            try:
                start = int(start_str) if start_str else 1
                end = int(end_str) if end_str else None  # None = open-ended
            except ValueError:
                raise ValueError(f"invalid range: non-numeric endpoint in '{part}'") from None
            if start < 1:
                raise ValueError(f"field numbers must be >= 1, got {start} in '{part}'")
            if end is not None:
                if end < 1:
                    raise ValueError(f"field numbers must be >= 1, got {end} in '{part}'")
                if end < start:
                    raise ValueError(f"invalid range: start {start} > end {end} in '{part}'")
            ranges.append((start, end))
        else:
            try:
                n = int(part)
            except ValueError:
                raise ValueError(f"invalid field value: '{part}'") from None
            if n < 1:
                raise ValueError(f"field numbers must be >= 1, got {n}")
            ranges.append((n, n))
    return ranges


def selected_indices(ranges):
    """Yield sorted unique field indices covered by the parsed ranges."""
    seen = set()
    for start, end in ranges:
        limit = end if end is not None else float("inf")
        n = start
        while n <= limit:
            seen.add(n)
            yield n
            n += 1
    # ensure determinism; generator above already yields sorted per range,
    # but dedupe across overlapping ranges happens via `seen` check order.


def process_line(line, ranges, delim, suppress):
    if delim not in line:
        return "" if suppress else line
    fields = line.split(delim)

    # Build output from ranges in ascending order, deduplicated.
    picked = []
    seen = set()
    for start, end in ranges:
        hi = end if end is not None else len(fields)
        for n in range(start, min(hi, len(fields)) + 1):
            if n not in seen:
                seen.add(n)
                picked.append(fields[n - 1])
    return delim.join(picked)


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="cut",
        description="Print selected parts of lines (fields mode).",
        usage="cut.py [-s] -d DELIM -f LIST [FILE ...]",
    )
    parser.add_argument("-d", "--delimiter", default="\t", metavar="DELIM")
    parser.add_argument("-f", "--fields", required=True, metavar="LIST")
    parser.add_argument(
        "-s", "--suppress",
        action="store_true",
        help="do not print lines lacking the delimiter",
    )
    parser.add_argument("files", nargs="*", metavar="FILE")

    args = parser.parse_args(argv)

    if len(args.delimiter) != 1:
        print(
            f"{parser.prog}: the delimiter must be a single character",
            file=sys.stderr,
        )
        return 2

    try:
        ranges = parse_field_list(args.fields)
    except ValueError as exc:
        print(f"{parser.prog}: {exc}", file=sys.stderr)
        return 2

    exit_code = 0
    if args.files:
        streams = []
        for path in args.files:
            try:
                streams.append(open(path, "r"))
            except OSError as exc:
                print(f"{parser.prog}: {exc}", file=sys.stderr)
                exit_code = 1
        import contextlib
        with contextlib.ExitStack() as stack:
            for s in streams:
                stack.enter_context(s)
            for stream in streams:
                for line in stream:
                    sys.stdout.write(
                        process_line(line.rstrip("\n"), ranges, args.delimiter, args.suppress) + "\n"
                    )
    else:
        for line in sys.stdin:
            sys.stdout.write(
                process_line(line.rstrip("\n"), ranges, args.delimiter, args.suppress) + "\n"
            )
    return exit_code


if __name__ == "__main__":
    sys.exit(main())

